parameters.query:
SELECT id, first_name, last_name, email, company_name, metadata 
FROM leads 
WHERE id = '{{ $json.body.lead_id }}';

parameters.jsCode:
const lead = $input.first().json;
const metadata = lead.metadata || {};

// Đọc ghi chú và ngân sách từ DB (hoặc lấy từ payload webhook nếu có truyền đè)
const notes = metadata.notes || $('Webhook').first().json.body?.interaction_notes || '';
const budget = metadata.budget || $('Webhook').first().json.body?.budget || 0;

let score = 40; // Điểm cơ sở
let reasons = [];

// 1. Tiêu chí Ngân sách (Budget)
if (budget >= 10000) {
  score += 30;
  reasons.push("Ngân sách cao (>= $10,000)");
} else if (budget >= 3000) {
  score += 15;
  reasons.push("Ngân sách trung bình");
}

// 2. Tiêu chí Mức độ cấp thiết / Nhu cầu (Need & Timeline)
if (/gấp|enterprise|báo giá|triển khai ngay/i.test(notes)) {
  score += 25;
  reasons.push("Nhu cầu cấp thiết và quan tâm gói Enterprise");
}

// 3. Tiêu chí Email doanh nghiệp (Authority)
if (lead.email && !/@(gmail|yahoo|hotmail)\.com$/i.test(lead.email)) {
  score += 10;
  reasons.push("Sử dụng email doanh nghiệp xác thực");
}

// Giới hạn điểm 0 - 100
score = Math.min(100, Math.max(0, score));

// Phân loại Tier
let tier = 'COLD';
if (score >= 80) tier = 'HOT';
else if (score >= 50) tier = 'WARM';

return [{
  json: {
    lead_id: lead.id,
    lead_name: `${lead.first_name || ''} ${lead.last_name || ''}`.trim(),
    score: score,
    tier: tier,
    reasoning: reasons.join("; ") || "Chưa có đủ tín hiệu tương tác"
  }
}];
